    lcdNibble(3);
    lcdNibble(3);
    lcdNibble(2);
    lcdSend(0x28, 0);
    lcdSend(0x0C, 0);
    lcdSend(0x06, 0);
    lcdSend(0x01, 0);
    char line1[] = "STM Emulator";
    char line2[] = "HAL 4-bit LCD";
    lcdPrint(line1);
    lcdSend(0xC0, 0);
    lcdPrint(line2);
