}
void tmData(uint32_t state) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, state?GPIO_PIN_SET:GPIO_PIN_RESET);
    HAL_Delay(1);
}
void tmStart(void) {
    tmData(1);
    tmClock(1);
    tmData(0);
    tmClock(0);
}
void tmStop(void) {
    tmClock(0);
    tmData(0);
    tmClock(1);
    tmData(1);
}
void tmByte(uint8_t value) {
    for (uint32_t bit=0;bit<8;bit++) {
        tmClock(0);
        tmData(value&1);
        tmClock(1);
        value>>=1;
    }
    GPIO_InitTypeDef ack={0};
    ack.Pin=GPIO_PIN_1;
    ack.Mode=GPIO_MODE_INPUT;
    ack.Pull=GPIO_PULLUP;
    HAL_GPIO_Init(GPIOB, &ack);
    tmClock(0);
    tmClock(1);
    if (HAL_GPIO_ReadPin(GPIOB, GPIO_PIN_1))printf("TM1637 NACK\n");
    tmClock(0);
    ack.Mode=GPIO_MODE_OUTPUT_PP;
    HAL_GPIO_Init(GPIOB, &ack);
}
