    R_IIC_MASTER_Read(&g_i2c_master0_ctrl, readback, 1, false);
    nack_seen = (I2C_MASTER_EVENT_ABORTED == wait_i2c());

    while (1)
    {
        R_IOPORT_PinWrite(&g_ioport_ctrl, LED1, BSP_IO_LEVEL_HIGH);
