/* Sends a line on SCI9 and waits until it has gone out (the clocks of SCI9 stop in Deep Software Standby). */
static void say(const char *text)
{
    tx_done = false;
    R_SCI_UART_Write(&g_uart9_ctrl, (uint8_t *) text, (uint32_t) strlen(text));
    while (!tx_done)
